
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

export default function MarkdownMessage({ content = "" }) {
  // Convert literal HTML line breaks generated by the AI
  // into actual Markdown line breaks.
  const formattedContent = content
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/\r\n/g, "\n");

  return (
    <div className="markdown-message">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          h1: ({ children }) => (
            <h1 className="markdown-h1">{children}</h1>
          ),
          h2: ({ children }) => (
            <h2 className="markdown-h2">{children}</h2>
          ),
          h3: ({ children }) => (
            <h3 className="markdown-h3">{children}</h3>
          ),
          p: ({ children }) => (
            <p className="markdown-paragraph">{children}</p>
          ),
          ul: ({ children }) => (
            <ul className="markdown-list">{children}</ul>
          ),
          ol: ({ children }) => (
            <ol className="markdown-list">{children}</ol>
          ),
          li: ({ children }) => (
            <li>{children}</li>
          ),
          table: ({ children }) => (
            <div className="markdown-table-wrapper">
              <table>{children}</table>
            </div>
          ),
          pre: ({ children }) => (
            <pre className="markdown-code-block">{children}</pre>
          ),
          code: ({ className, children, ...props }) => {
            const isBlock = Boolean(className);

            return isBlock ? (
              <code className={className} {...props}>
                {children}
              </code>
            ) : (
              <code className="markdown-inline-code" {...props}>
                {children}
              </code>
            );
          },
          blockquote: ({ children }) => (
            <blockquote className="markdown-blockquote">
              {children}
            </blockquote>
          )
        }}
      >
        {formattedContent}
      </ReactMarkdown>
    </div>
  );
}
